function IdolLive3D_MainForRuntime:__init()
    self.controller = nil
    self.isInit = false
end


function IdolLive3D_MainForRuntime:__delete()
end



function IdolLive3D_MainForRuntime:Start()
    KTool.SetActive(self.controller.gameObject, true);
    -- ==============================
    -- 绑定 Update() 函数:
    local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    if behaviourAction then
        behaviourAction.UpdateAction = function(behaviourAction)
            self:Update()
        end
    end

    -- PC / Mobile 平台:
    if IdolLive3D_States.expectedPlatformType == IdolLive3D_States.PlatformType.Auto then 
        IdolLive3D_States.isWindowsPlatform = IdolLive3D_Utils.IsReallyPCPlatform() 
    else 
        IdolLive3D_States.isWindowsPlatform = (IdolLive3D_States.expectedPlatformType == IdolLive3D_States.PlatformType.PC)
    end 
end


---@param skinId_ number @ 皮肤id
---@param roleTF_ UnityEngine.Transform @ 角色根节点
---@param runtimeRootTF_ UnityEngine.Transform
---@param timelineTFMaps_ table            @ 一组 timelineStates tfs
---@param superTimelineTFMaps_ table        @ 一组 super timelineStates tfs
---@param simpleFxTFMaps_ table
---@param allResources_   table
---@param baseJson_ IdolLive3D_BaseParamsJsonData         @ baseParams json 数据 
---@param animatorController_ UnityEngine.RuntimeAnimatorController 
---@param isSmlPackage_ boolean 
---@param isLockFreeCamera_ boolean
---@param isDemo_ boolean   @ 是否是试玩版
function IdolLive3D_MainForRuntime:Init( skinId_, roleTF_, runtimeRootTF_, timelineTFMaps_, superTimelineTFMaps_, simpleFxTFMaps_, allResources_, baseJson_, animatorController_, isSmlPackage_, isLockFreeCamera_, isDemo_ )
    print("=== IdolLive3D_MainForRuntime start ===")
    assert( isNotNull(roleTF_) )

    --Application.targetFrameRate = 60 -- todo: debug

    self.skinId = skinId_
    self.baseJson = baseJson_
    self.allResources = allResources_
    ------------------------- 
    self.mainCamera = IdolLive3D_Utils.GetMainCamera()
    self.isDemo = (isDemo_ == true)

    if isSmlPackage_ == false then
        local uiMainTable = {} 
        Events.Broadcast(IdolLive3D_States.EventGetUIMain, uiMainTable)
        self.uiMain = uiMainTable.uiMain
        assert( isNotNull(self.uiMain) )
    end

    -- ==============================
    self.roleTF = roleTF_
    self.roleLookAtController = KTool.GetComponent(self.roleTF.gameObject, typeof(LookAtController))
    self.roleAnimator = KTool.GetComponent(self.roleTF.gameObject, typeof(Animator))
    assert( isNotNull(self.roleLookAtController) and isNotNull(self.roleAnimator) )

    -- 在 role 体内准备 CriAtomSource go:
    IdolLive3D_Sounds:AddCRIAtomSource_SFX( roleTF_ )

    ---
    self.idolLive3D_FreeNodesMgr = IdolLive3D_FreeNodesMgr.New()

    -- (1) 先置空, 避免下面开启 IK 时角色不在 T-pos:
    self.roleAnimator.runtimeAnimatorController = nil
    
    -- (2) 主动开启 IK:  
    local lookAtIK = KTool.GetComponent(self.roleTF.gameObject, typeof(LookAtIK))
    assert(lookAtIK)
    lookAtIK.enabled = true


    -- 绑定 animator controller: 
    -- !!! 延迟一帧后再绑定 动画状态机, 否则如果 状态机默认初始动作是背对着玩家的, 那会导致 lookatik 出现异常, 不再看着相机
    self.neededAnimatorController = animatorController_
    ---
    IdolLive3D_Utils.StopCoroutine(self.co_2)
    self.co_2 = cs_coroutine.start(function()
        coroutine.yield(Yielders.EndOfFrame)
        ---
        if isNull(self.neededAnimatorController) then 
            printError("参数 animatorController_ 为空")
        else 
            self.roleAnimator.runtimeAnimatorController = self.neededAnimatorController
        end
    end) 


    -- 绑定 customLightDirRelativeCamera.RelativeCamera:
    -- 有些 角色 prefab 可能不带此组件
    self.customLightDirRelativeCamera = KTool.GetOrAddComponent(self.roleTF.gameObject, typeof(CustomLightDirRelativeCamera))
    if isNull(self.customLightDirRelativeCamera) then 
        printError("koko - 异常, role 没绑定 self.CustomLightDirRelativeCamera 脚本")
        return
    end
    self.customLightDirRelativeCamera.RelativeCamera = self.mainCamera
    self.customLightDirRelativeCamera.DelayUpdate = true

    ------------------
    assert(self.idolCamera) 
    ---@type IdolLive3D_Camera
    self.idolLive3D_CameraEnv = IdolLive3D_Utils.GetLuaScr(self.idolCamera.gameObject, "Game.IdolLive3D.IdolLive3D_Camera" )
    assert( self.idolLive3D_CameraEnv )
    self.idolLive3D_CameraEnv:Init(self)

    ---
    assert(self.idolInteractive) 
    ---@type IdolLive3D_InteractiveManager
    self.idolLive3D_InteractiveManagerEnv = IdolLive3D_Utils.GetLuaScr(self.idolInteractive.gameObject, "Game.IdolLive3D.Interactive.IdolLive3D_InteractiveManager" )
    assert( self.idolLive3D_InteractiveManagerEnv )
    self.idolLive3D_InteractiveManagerEnv:Init(self, runtimeRootTF_, self.idolLive3D_CameraEnv, lookAtIK, self.roleAnimator, timelineTFMaps_, superTimelineTFMaps_, simpleFxTFMaps_, allResources_ )

    ---
    assert(self.idolTextDebug) 
    ---@type IdolLive3D_TextDebug
    self.idolLive3D_TextDebugEnv = IdolLive3D_Utils.GetLuaScr(self.idolTextDebug.gameObject, "Game.IdolLive3D.IdolLive3D_TextDebug" )
    assert( self.idolLive3D_TextDebugEnv )

    ---@type IdolLive3D_Input
    self.idolLive3D_Input = IdolLive3D_Input.New(self)

    -- 反绑参数:
    self.idolLive3D_InteractiveManagerEnv:BindSimpleTap( self.idolLive3D_Input )
    self.idolLive3D_CameraEnv:BindInput( self.idolLive3D_Input )

    -- !! 二段包角色的 近景特写+相机冻结 改为外部调用 IdolLive3D_States.EventSmlPackageInitFreeze 来实现:
    --[[
    if isSmlPackage_==true and isLockFreeCamera_==true then 
        -- 二段包的一种入场方式: 进去就 cut 到一个近景, 且锁 free camera
        -- !!! 这里的时序出问题了, 如果不等到两帧再执行, 会导致这个镜头锁定被丢失; 先用以下暴力方法克服, 晚点来实现正式修改
        IdolLive3D_Utils.StopCoroutine(self.co_3)
        self.co_3 = cs_coroutine.start(function()
            coroutine.yield(Yielders.EndOfFrame)
            coroutine.yield(Yielders.EndOfFrame)
            --self.idolLive3D_CameraEnv:InitToFreezeState( IdolLive3D_States.GameInstaller.tgtFreeCameraParams, true )
        end)
    else    
        --  启动 入场小动画:
        --self.idolLive3D_CameraEnv:PlayInitAnimation()
    end 
    ]]

    --- 
    self.allRoleTFs = { roleTF_ }
    for _,tf in pairs(timelineTFMaps_) do 
        table.insert( self.allRoleTFs, tf )
    end
    for _,se in pairs(superTimelineTFMaps_) do 
        for __,tf in pairs(se) do
            table.insert( self.allRoleTFs, tf )
        end
    end
    for _,tf in pairs(simpleFxTFMaps_) do 
        table.insert( self.allRoleTFs, tf )
    end

    ---
    local initIdleState = self.baseJson:GetInitIdleState()
    self:OnSwitchIdle( initIdleState.idleType )

    --------- 皮肤定制脚本 --------
    local skinLuaEnv = self.baseJson.data.oths.skinLuaEnv
    if isNotNull(skinLuaEnv) and isNotNull(skinLuaEnv.OnMainInitEnd) then 
        skinLuaEnv:OnMainInitEnd( self )
    end


    --------- 试玩版 --------
    if self.isDemo then 
        self.demoEnv = IdolLive3D_Demo.New(self)
    end

    --
    self.isInit = true
end



function IdolLive3D_MainForRuntime:OnDestroy()
    if isNotNull(self.idolLive3D_Input) then 
        self.idolLive3D_Input:Delete() -- !! MUST
    end 

    if isNotNull(self.demoEnv) then 
        self.demoEnv:Delete() -- !! MUST
    end 

    if isNotNull(self.idolLive3D_FreeNodesMgr) then 
        self.idolLive3D_FreeNodesMgr:Delete() -- !! MUST
    end 

    IdolLive3D_Utils.StopCoroutine(self.co_1)
    IdolLive3D_Utils.StopCoroutine(self.co_2)
    IdolLive3D_Utils.StopCoroutine(self.co_3)

    ---
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end


