function IdolLive3D_MainForRuntime:IsInit()
    return (self.isInit == true)
end



function IdolLive3D_MainForRuntime:Update()
    if self.isInit ~= true then 
        return
    end
    self.idolLive3D_Input:SelfUpdate()
    self.idolLive3D_InteractiveManagerEnv:SelfUpdate()
    self.idolLive3D_CameraEnv:SelfUpdate()

    if isNotNull(self.demoEnv) then 
        self.demoEnv:SelfUpdate()
    end     
end




-- 切入不同 idle 后, role pos 可能调整, 相应的, 定制光照参数也要调整;
function IdolLive3D_MainForRuntime:OnSwitchIdle( idleType_ )
    assert( idleType_ == IdleType.Type_100 or idleType_ == IdleType.Type_200 )
    local tgtIdle = self.baseJson:IdleType_To_IdleState(idleType_, false)
    for _,tf in pairs(self.allRoleTFs) do 
        tf.position = tgtIdle.rolePos
    end

    if tgtIdle.customLightDir.magnitude > 0.01 then 
        self.customLightDirRelativeCamera.CustomLightDirection = tgtIdle.customLightDir
    end     
end






return IdolLive3D_MainForRuntime
